import java.util.*;

class Solution {
    public int josephus(int n, int k) {
        LinkedList<Integer> circle = new LinkedList<>();

        for (int person = 1; person <= n; person++) {
            circle.add(person);
        }

        int currentIndex = 0;

        while (circle.size() > 1) {
            for (int steps = 1; steps < k; steps++) {
                currentIndex++;
                if (currentIndex == circle.size()) {
                    currentIndex = 0;
                }
            }

            circle.remove(currentIndex);

            if (currentIndex == circle.size() && circle.size() > 0) {
                currentIndex = 0;
            }
        }

        return circle.getFirst();
    }
}
